mapper.select:
select r.* from CF_ROLES r where 1=1

    and r.roleName = #{roleName}

${roleCondition}

select distinct r.* from CF_ROLES r inner join CF_USERROLES ur on r.ROLEID = ur.ROLEID where 1=1
and ur.USERID = #{userId}
order by r.ORDERBY desc

select ifnull(min(dc.DICKEY), 999)
from CF_USERROLES us
inner join CF_ROLES  r on us.ROLEID=r.ROLEID
left join CF_DICTIONARY dc on r.DICTIONARYID=dc.DICTIONARYID
where us.USERID=#{userId}

    and r.roleId = #{roleId}
